-- One fixed price for every website, no add-on surcharges, and full A-to-Z details for every package.
-- Generated once from scripts/demo-content.mjs; afterwards everything is edited in the admin panel.

ALTER TABLE packages ADD COLUMN feature_groups TEXT NOT NULL DEFAULT '[]'; -- JSON [{title, items[]}]: "A থেকে Z সব ফিচার"
ALTER TABLE packages ADD COLUMN screen_tour TEXT NOT NULL DEFAULT '[]';    -- JSON [{image, title, text}]: screenshot feature tour

-- Every website costs the same (owner's instruction: ৳12000). Edit any package's price in admin.
UPDATE packages SET base_price = 12000;
-- Add-ons no longer raise the price on the package page. They are kept (switched off) — turn any back on in admin.
UPDATE package_addons SET is_active = 0;
-- The old generic example packages (no demo, no screenshot) are hidden even if they were edited. Kept, not deleted.
UPDATE packages SET status = 'inactive', is_featured = 0 WHERE slug IN ('fashion-basic', 'fashion-premium', 'clothing-basic', 'clothing-premium', 'gadgets-basic', 'gadgets-premium', 'herbal-basic', 'herbal-premium', 'news-basic', 'news-premium', 'blog-basic', 'blog-premium');
UPDATE faqs SET question = '৳১২,০০০ প্যাকেজে কী কী পাবো?' WHERE question = '৳১০,০০০ প্যাকেজে কী কী পাবো?';


UPDATE packages SET feature_groups = '[{"title":"মার্কেটপ্লেস — ক্রেতা যা দেখেন","items":["PUBG Mobile UC, Free Fire ও Mobile Legends ডায়মন্ড, Call of Duty CP, Google Play ও Steam কোড","একটি প্যাকের সব সেলারের অফার এক পেজে — সবচেয়ে কম দাম আগে, রেটিং ও ডেলিভারির গতিসহ","পেমেন্টের আগে প্লেয়ার আইডির ফরম্যাট যাচাই ও আবার দেখানো","ফোন যাচাই, ইনভয়েস পিডিএফ, বিরোধ ও সেলার রিভিউ","বাংলা ও ইংরেজি"]},{"title":"পেমেন্ট ও ডেলিভারির নিরাপত্তা","items":["সার্ভারে পেমেন্ট নিশ্চিত হওয়ার পরেই কোড দেখায় বা টপ-আপ সেলারের কাছে যায়","পেমেন্ট বাতিল হলে কিছুই ডেলিভারি হয় না","প্রথম বড় অর্ডার নিরাপত্তা যাচাইয়ের জন্য হোল্ডে থাকে","ক্রেতার যোগাযোগ বা পেমেন্টের তথ্য সেলার দেখতে পান না"]},{"title":"সেলার ড্যাশবোর্ড","items":["আজকের ডেলিভারি ও আয়, ভেরিফায়েড ব্যাজের অগ্রগতি","৩০ মিনিটের টাইমারসহ টপ-আপ ডেলিভারি কিউ","স্বয়ংক্রিয় SKU-সহ লিস্টিং","এনক্রিপ্টেড কোড স্টক, ডুপ্লিকেট কোড স্বয়ংক্রিয়ভাবে বাদ","হোল্ড সময়ের পর পেআউট অনুরোধ, রিভিউ ও বিরোধের উত্তর","নতুন সেলারের জন্য KYC আবেদন"]},{"title":"প্ল্যাটফর্ম অ্যাডমিন","items":["সেলার আবেদন যাচাই: অনুমোদন / বাতিল / আরও তথ্য চাওয়া","সব সেলারের অর্ডার: পেমেন্ট নিশ্চিত, রিলিজ, রিফান্ড ও অন্য সেলারে হস্তান্তর","বিরোধে দুই পক্ষের প্রমাণ পাশাপাশি — রিফান্ড, সেলারকে পেমেন্ট বা ভাগ","কমিশনের নিয়ম ও পেআউট","ফ্রড ও রিস্ক: বিশ্বস্ত / নতুন / যাচাই প্রয়োজন ক্রেতা ও সেলারের অবস্থা","রিভিউ, রিপোর্ট, স্টাফ রোল, অ্যাক্টিভিটি লগ ও সিএসভি এক্সপোর্ট","দুই ধাপের সাইন-ইন (অথেনটিকেটর অ্যাপ)"]}]', screen_tour = '[{"image":"/assets/demos/cwb-gaming/cover.webp","title":"হোমপেজ","text":"গেম ও প্যাক বেছে নেওয়ার হোমপেজ — জনপ্রিয় গেম, অফার ও “সেলার তুলনা করে নিরাপদ পেমেন্ট” প্রতিশ্রুতি প্রথম স্ক্রিনেই।"},{"image":"/assets/demos/cwb-gaming/admin.webp","title":"অ্যাডমিন ড্যাশবোর্ড","text":"প্ল্যাটফর্ম অ্যাডমিন — সেলার আবেদন, হোল্ড করা অর্ডার, বিরোধ ও পেআউট অনুরোধ এক জায়গায়।"},{"image":"/assets/demos/cwb-gaming/sidebar.webp","title":"অ্যাডমিন মেনু","text":"অর্ডার, সেলার আবেদন, গেম ও প্যাক, পেআউট, কমিশন, বিরোধ, ফ্রড ও রিস্ক — সব মেনু এক পাশে।"},{"image":"/assets/demos/cwb-gaming/mobile.webp","title":"মোবাইল ভিউ","text":"বেশিরভাগ ক্রেতা ফোনে কেনেন — তাই বড় বোতাম, নিচে নেভিগেশন বার আর দ্রুত লোডিং।"},{"image":"/assets/demos/cwb-gaming/section.webp","title":"হোমপেজের আরও অংশ","text":"নিচে স্ক্রল করলে জনপ্রিয় পণ্য, ক্যাটাগরি ও অফার সাজানো থাকে — ক্রেতা ঘুরে ঘুরে দেখেন।"}]' WHERE slug = 'cwb-gaming';

UPDATE packages SET feature_groups = '[{"title":"দোকান — ক্রেতা যা দেখেন","items":["হোমপেজে ব্যানার, অফার স্ট্রিপ ও ক্যাটাগরি","ক্যাটাগরি পেজে ফিল্টার, সর্টিং ও সার্চ","পণ্যের পেজে ছবি, দাম, ছাড়, স্টক ও বিস্তারিত","যাচাইকৃত ক্রেতার রিভিউ","বাংলা ও ইংরেজি — এক চাপে ভাষা বদল","মোবাইলে নিচে নেভিগেশন বার ও হোয়াটসঅ্যাপ বোতাম","“কোন ডিভাইসে চলে” ফিল্টার: iPhone, Android, USB-C, ল্যাপটপ, PS5, Switch","আসল স্পেক শিট ও ২–৩টি পণ্যের স্পেক তুলনা","গ্যাজেট ফাইন্ডার: ডিভাইস ও বাজেট দিলে প্রতিটি শেলফ থেকে একটি প্রয়োজনীয় পণ্য","কম্বো বান্ডেলে আসল সাশ্রয়, সৎ “ডিল অব দ্য ডে” কাউন্টডাউন","ওয়ারেন্টি ব্যাজ ও শর্তাবলি পণ্যের পাশেই"]},{"title":"কার্ট, চেকআউট ও পেমেন্ট","items":["কার্ট ও এক পেজের চেকআউট","বিভাগ → জেলা → উপজেলা ঠিকানা, জোনভিত্তিক লাইভ ডেলিভারি চার্জ","চেকআউটে ফোন নম্বর যাচাই (এসএমএস কোড)","ক্যাশ অন ডেলিভারি ও মোবাইল ব্যাংকিং","কুপন কোড","প্রতিটি অর্ডারে অর্ডার নম্বর, ইনভয়েস নম্বর ও পিডিএফ ইনভয়েস","অর্ডার ট্র্যাকিং ও শপার অ্যাকাউন্ট (ফোন নম্বর দিয়ে সাইন ইন)","অর্ডার লাইন থেকে ওয়ারেন্টি ক্লেইম — সিরিয়াল ও মেয়াদ মিলিয়ে"]},{"title":"অ্যাডমিন প্যানেল — দোকান চালানো","items":["“আজ যেগুলোতে নজর দরকার” — কল বাকি অর্ডার, কম স্টক, অপেক্ষমাণ রিভিউ","অর্ডার পাইপলাইন: পেন্ডিং → কনফার্ম → প্যাক → শিপ → ডেলিভারি, রিটার্ন ও বাতিল","ফেক অর্ডার সুরক্ষা: বিশ্বস্ত / নতুন / যাচাই প্রয়োজন — কল লগ ছাড়া ক্যাশ অন ডেলিভারি অর্ডার কনফার্ম হয় না","প্রতিটি অর্ডারে ইনভয়েস পিডিএফ, কল ও হোয়াটসঅ্যাপ বোতাম","পণ্য, SKU, স্টক ও ছবি ম্যানেজমেন্ট","কুপন, ব্যানার, রিভিউ অনুমোদন ও ডেলিভারি জোন","পরিত্যক্ত চেকআউটের তালিকা — আগ্রহী ক্রেতাকে আবার ধরুন","অর্ডার নম্বর, ইনভয়েস নম্বর, ফোন বা SKU দিয়ে সার্চ","রিপোর্ট ও চার্ট; প্রতিটি তালিকা সিএসভি এক্সপোর্ট","স্টাফ রোল, ফোনে স্টাফ সাইন-ইন ও অ্যাক্টিভিটি লগ","স্পেক শিট এডিটর ও স্বয়ংক্রিয় SKU","প্যাক করার সময় প্রতিটি লাইনের সিরিয়াল নম্বর — ইনভয়েসে ছাপা হয়","সাপ্লায়ার ইনভয়েস অনুযায়ী স্টক লট","ওয়ারেন্টি ক্লেইম: জমা থেকে সমাধান পর্যন্ত","কম্বো বান্ডেল, রিভিউ ও প্রশ্নোত্তর"]}]', screen_tour = '[{"image":"/assets/demos/gadget-market/cover.webp","title":"হোমপেজ","text":"প্রথম স্ক্রিনেই ব্যানার, অফার ও মূল ক্যাটাগরি — ক্রেতা সাথে সাথে বুঝে যান আপনি কী বিক্রি করেন এবং কোথায় চাপ দিতে হবে।"},{"image":"/assets/demos/gadget-market/product.webp","title":"পণ্যের পেজ","text":"স্পেক শিট, ওয়ারেন্টি ব্যাজ, “কোন ডিভাইসে চলে” তথ্য আর কম্বো অফার — গ্যাজেট কেনার আগে ক্রেতা যা জানতে চান, সব পণ্যের পেজেই।"},{"image":"/assets/demos/gadget-market/checkout.webp","title":"চেকআউট","text":"ফোন নম্বর যাচাই, বিভাগ-জেলা-উপজেলা ঠিকানা, জোনভিত্তিক ডেলিভারি চার্জ, কুপন আর পেমেন্ট মাধ্যম — সব এক পেজে।"},{"image":"/assets/demos/gadget-market/admin.webp","title":"অ্যাডমিন ড্যাশবোর্ড","text":"“আজ যেগুলোতে নজর দরকার” — কল বাকি অর্ডার, কম স্টক, অপেক্ষমাণ রিভিউ — আর আজকের বিক্রি ও অর্ডার এক নজরে।"},{"image":"/assets/demos/gadget-market/sidebar.webp","title":"অ্যাডমিন মেনু","text":"অর্ডার, পণ্য, কাস্টমার, কুপন, রিপোর্ট, সেটিংস — বাম পাশের মেনু থেকে এক চাপে।"},{"image":"/assets/demos/gadget-market/mobile.webp","title":"মোবাইল ভিউ","text":"বেশিরভাগ ক্রেতা ফোনে কেনেন — তাই বড় বোতাম, নিচে নেভিগেশন বার আর দ্রুত লোডিং।"},{"image":"/assets/demos/gadget-market/section.webp","title":"হোমপেজের আরও অংশ","text":"নিচে স্ক্রল করলে জনপ্রিয় পণ্য, ক্যাটাগরি ও অফার সাজানো থাকে — ক্রেতা ঘুরে ঘুরে দেখেন।"}]' WHERE slug = 'gadget-market';

