INSERT INTO settings (key, value) VALUES ('common_features', '"আপনার ব্র্যান্ডে সাজানো — লোগো, রং, লেখা ও যোগাযোগের তথ্য\nআপনার প্রথম পণ্য ও ক্যাটাগরি বসিয়ে দেওয়া\nআপনার ডোমেইনে সেটআপ ও এসএসএল (https)\nমোবাইল, ট্যাবলেট ও কম্পিউটার — সব স্ক্রিনে সুন্দর\nদ্রুত লোডিং ও বেসিক এসইও: টাইটেল, বিবরণ, সাইটম্যাপ\nমেটা পিক্সেল, কনভার্সন এপিআই ও গুগল অ্যানালিটিক্স সেটআপ\nঅ্যাডমিন প্যানেল ব্যবহারের প্রশিক্ষণ\nডেলিভারির পর ১ মাস ফ্রি সাপোর্ট"') ON CONFLICT(key) DO NOTHING;
INSERT INTO faqs (question, answer, scope, package_id, sort_order) SELECT 'CWB Gaming ডেমোতে যা দেখছি, সবই কি আমার সাইটে থাকবে?', 'হ্যাঁ। ডেমোর সব ফিচার — যেমন একই প্যাকের সব সেলারের দাম, রেটিং ও ডেলিভারি সময় পাশাপাশি তুলনা; পেমেন্টের আগে প্লেয়ার আইডি যাচাই ও আবার দেখানো; সার্ভারে পেমেন্ট নিশ্চিত হওয়ার পরেই কোড/টপ-আপ ডেলিভারি — আপনার সাইটে থাকবে। ডেমোর কাল্পনিক পণ্য ও তথ্যের জায়গায় আপনার লোগো, রং, পণ্য ও যোগাযোগের তথ্য বসবে।', 'package', id, 1 FROM packages WHERE slug = 'cwb-gaming' AND NOT EXISTS (SELECT 1 FROM faqs f WHERE f.package_id = packages.id AND f.question = 'CWB Gaming ডেমোতে যা দেখছি, সবই কি আমার সাইটে থাকবে?');
INSERT INTO faqs (question, answer, scope, package_id, sort_order) SELECT 'অ্যাডমিন প্যানেল থেকে আমি নিজে কী কী করতে পারব?', 'সেলার অনুমোদন, সব অর্ডার, বিরোধ, কমিশন ও পেআউট, ফ্রড চিহ্ন, রিভিউ, রিপোর্ট ও স্টাফ — সবই অ্যাডমিন থেকে। সেলাররা নিজেদের ড্যাশবোর্ড থেকে লিস্টিং, কোড স্টক ও ডেলিভারি সামলান।', 'package', id, 2 FROM packages WHERE slug = 'cwb-gaming' AND NOT EXISTS (SELECT 1 FROM faqs f WHERE f.package_id = packages.id AND f.question = 'অ্যাডমিন প্যানেল থেকে আমি নিজে কী কী করতে পারব?');
INSERT INTO faqs (question, answer, scope, package_id, sort_order) SELECT 'দাম কি একবারই? পরে কোনো লুকানো খরচ আছে?', 'সাইট তৈরি ও সেটআপের দাম ৳১২,০০০ — একবারই। ডোমেইন, এসএমএস বা পেমেন্ট গেটওয়ের নিজস্ব চার্জ (যদি নেন) সংশ্লিষ্ট কোম্পানিকে আলাদা দিতে হয় — অর্ডারের আগেই আমরা পরিষ্কার জানিয়ে দেব।', 'package', id, 3 FROM packages WHERE slug = 'cwb-gaming' AND NOT EXISTS (SELECT 1 FROM faqs f WHERE f.package_id = packages.id AND f.question = 'দাম কি একবারই? পরে কোনো লুকানো খরচ আছে?');
INSERT INTO faqs (question, answer, scope, package_id, sort_order) SELECT 'কত দিনে সাইট পাব?', 'পেমেন্ট নিশ্চিত হওয়ার পর আপনার লোগো, পণ্যের ছবি ও দাম পেলে সাধারণত ১৪ কর্মদিবসে। প্রতিটি ধাপের আপডেট আপনার অর্ডার পেজে পাবেন।', 'package', id, 4 FROM packages WHERE slug = 'cwb-gaming' AND NOT EXISTS (SELECT 1 FROM faqs f WHERE f.package_id = packages.id AND f.question = 'কত দিনে সাইট পাব?');
INSERT INTO faqs (question, answer, scope, package_id, sort_order) SELECT 'টপ-আপ কি স্বয়ংক্রিয়ভাবে ডেলিভারি হয়?', 'গিফট কোড পেমেন্ট নিশ্চিত হলেই স্বয়ংক্রিয়ভাবে দেখায়। সরাসরি টপ-আপ (প্লেয়ার আইডিতে) সেলারের কিউতে ৩০ মিনিটের টাইমারসহ যায় — সেলার ডেলিভারি দিলে ক্রেতার অর্ডার পেজ হালনাগাদ হয়।', 'package', id, 5 FROM packages WHERE slug = 'cwb-gaming' AND NOT EXISTS (SELECT 1 FROM faqs f WHERE f.package_id = packages.id AND f.question = 'টপ-আপ কি স্বয়ংক্রিয়ভাবে ডেলিভারি হয়?');
INSERT INTO faqs (question, answer, scope, package_id, sort_order) SELECT 'Gadget Market ডেমোতে যা দেখছি, সবই কি আমার সাইটে থাকবে?', 'হ্যাঁ। ডেমোর সব ফিচার — যেমন “কোন ডিভাইসে চলে” ফিল্টার: iPhone, Android, USB-C, ল্যাপটপ, PS5 ইত্যাদি; ২–৩টি পণ্যের স্পেক পাশাপাশি তুলনা, পার্থক্য হাইলাইট করা; গ্যাজেট ফাইন্ডার: ডিভাইস ও বাজেট দিলে প্রয়োজনীয় পণ্য সাজেস্ট — আপনার সাইটে থাকবে। ডেমোর কাল্পনিক পণ্য ও তথ্যের জায়গায় আপনার লোগো, রং, পণ্য ও যোগাযোগের তথ্য বসবে।', 'package', id, 1 FROM packages WHERE slug = 'gadget-market' AND NOT EXISTS (SELECT 1 FROM faqs f WHERE f.package_id = packages.id AND f.question = 'Gadget Market ডেমোতে যা দেখছি, সবই কি আমার সাইটে থাকবে?');
INSERT INTO faqs (question, answer, scope, package_id, sort_order) SELECT 'অ্যাডমিন প্যানেল থেকে আমি নিজে কী কী করতে পারব?', 'অর্ডার কনফার্ম থেকে ডেলিভারি, ইনভয়েস, পণ্য ও স্পেক, সিরিয়াল নম্বর, ওয়ারেন্টি ক্লেইম, স্টক লট, কুপন, ব্যানার, ডেলিভারি জোন, স্টাফ ও রিপোর্ট — সবই অ্যাডমিন থেকে, কোড ছাড়াই।', 'package', id, 2 FROM packages WHERE slug = 'gadget-market' AND NOT EXISTS (SELECT 1 FROM faqs f WHERE f.package_id = packages.id AND f.question = 'অ্যাডমিন প্যানেল থেকে আমি নিজে কী কী করতে পারব?');
INSERT INTO faqs (question, answer, scope, package_id, sort_order) SELECT 'দাম কি একবারই? পরে কোনো লুকানো খরচ আছে?', 'সাইট তৈরি ও সেটআপের দাম ৳১২,০০০ — একবারই। ডোমেইন, এসএমএস বা পেমেন্ট গেটওয়ের নিজস্ব চার্জ (যদি নেন) সংশ্লিষ্ট কোম্পানিকে আলাদা দিতে হয় — অর্ডারের আগেই আমরা পরিষ্কার জানিয়ে দেব।', 'package', id, 3 FROM packages WHERE slug = 'gadget-market' AND NOT EXISTS (SELECT 1 FROM faqs f WHERE f.package_id = packages.id AND f.question = 'দাম কি একবারই? পরে কোনো লুকানো খরচ আছে?');
INSERT INTO faqs (question, answer, scope, package_id, sort_order) SELECT 'কত দিনে সাইট পাব?', 'পেমেন্ট নিশ্চিত হওয়ার পর আপনার লোগো, পণ্যের ছবি ও দাম পেলে সাধারণত ৭ কর্মদিবসে। প্রতিটি ধাপের আপডেট আপনার অর্ডার পেজে পাবেন।', 'package', id, 4 FROM packages WHERE slug = 'gadget-market' AND NOT EXISTS (SELECT 1 FROM faqs f WHERE f.package_id = packages.id AND f.question = 'কত দিনে সাইট পাব?');
INSERT INTO faqs (question, answer, scope, package_id, sort_order) SELECT 'পণ্যের স্পেক কি নিজে যোগ করতে পারব?', 'হ্যাঁ। অ্যাডমিনের স্পেক শিট এডিটরে প্রতিটি পণ্যের স্পেক লিখলেই পণ্যের পেজে ও তুলনায় দেখাবে।', 'package', id, 5 FROM packages WHERE slug = 'gadget-market' AND NOT EXISTS (SELECT 1 FROM faqs f WHERE f.package_id = packages.id AND f.question = 'পণ্যের স্পেক কি নিজে যোগ করতে পারব?');
INSERT INTO faqs (question, answer, scope, package_id, sort_order) SELECT 'Lk''s Attire ডেমোতে যা দেখছি, সবই কি আমার সাইটে থাকবে?', 'হ্যাঁ। ডেমোর সব ফিচার — যেমন আসল পণ্যের ছবি, ক্যাটাগরি, ফিল্টার ও সর্টিং; সাইজ ও রং বাছাইসহ পণ্যের পেজ, উইশলিস্ট ও রিভিউ; পোস্টকোড বা এলাকার নাম দিলেই ঠিকানা পূরণ, জোনভিত্তিক ডেলিভারি চার্জ — আপনার সাইটে থাকবে। ডেমোর কাল্পনিক পণ্য ও তথ্যের জায়গায় আপনার লোগো, রং, পণ্য ও যোগাযোগের তথ্য বসবে।', 'package', id, 1 FROM packages WHERE slug = 'lks-attire' AND NOT EXISTS (SELECT 1 FROM faqs f WHERE f.package_id = packages.id AND f.question = 'Lk''s Attire ডেমোতে যা দেখছি, সবই কি আমার সাইটে থাকবে?');
INSERT INTO faqs (question, answer, scope, package_id, sort_order) SELECT 'অ্যাডমিন প্যানেল থেকে আমি নিজে কী কী করতে পারব?', 'অর্ডার কনফার্ম থেকে ডেলিভারি ও রিফান্ড, ইনভয়েস ও শিপিং লেবেল, পণ্য ও ভ্যারিয়েন্ট, স্টক, কুপন, ব্যানার, ডেলিভারি জোন, স্টাফ — এমনকি লোগো, অফার স্ট্রিপ ও বিকাশ/নগদ নম্বরও কোড ছাড়া বদলানো যায়।', 'package', id, 2 FROM packages WHERE slug = 'lks-attire' AND NOT EXISTS (SELECT 1 FROM faqs f WHERE f.package_id = packages.id AND f.question = 'অ্যাডমিন প্যানেল থেকে আমি নিজে কী কী করতে পারব?');
INSERT INTO faqs (question, answer, scope, package_id, sort_order) SELECT 'দাম কি একবারই? পরে কোনো লুকানো খরচ আছে?', 'সাইট তৈরি ও সেটআপের দাম ৳১২,০০০ — একবারই। ডোমেইন, এসএমএস বা পেমেন্ট গেটওয়ের নিজস্ব চার্জ (যদি নেন) সংশ্লিষ্ট কোম্পানিকে আলাদা দিতে হয় — অর্ডারের আগেই আমরা পরিষ্কার জানিয়ে দেব।', 'package', id, 3 FROM packages WHERE slug = 'lks-attire' AND NOT EXISTS (SELECT 1 FROM faqs f WHERE f.package_id = packages.id AND f.question = 'দাম কি একবারই? পরে কোনো লুকানো খরচ আছে?');
INSERT INTO faqs (question, answer, scope, package_id, sort_order) SELECT 'কত দিনে সাইট পাব?', 'পেমেন্ট নিশ্চিত হওয়ার পর আপনার লোগো, পণ্যের ছবি ও দাম পেলে সাধারণত ৭ কর্মদিবসে। প্রতিটি ধাপের আপডেট আপনার অর্ডার পেজে পাবেন।', 'package', id, 4 FROM packages WHERE slug = 'lks-attire' AND NOT EXISTS (SELECT 1 FROM faqs f WHERE f.package_id = packages.id AND f.question = 'কত দিনে সাইট পাব?');
INSERT INTO faqs (question, answer, scope, package_id, sort_order) SELECT 'সাইজ ও রং কি প্রতিটি পণ্যে আলাদা করে দেওয়া যাবে?', 'হ্যাঁ। অ্যাডমিনের পণ্য এডিটরে প্রতিটি পণ্যের সাইজ, রং, SKU ও স্টক আলাদা করে দেওয়া যায়।', 'package', id, 5 FROM packages WHERE slug = 'lks-attire' AND NOT EXISTS (SELECT 1 FROM faqs f WHERE f.package_id = packages.id AND f.question = 'সাইজ ও রং কি প্রতিটি পণ্যে আলাদা করে দেওয়া যাবে?');
INSERT INTO faqs (question, answer, scope, package_id, sort_order) SELECT 'Prakriti Herbal ডেমোতে যা দেখছি, সবই কি আমার সাইটে থাকবে?', 'হ্যাঁ। ডেমোর সব ফিচার — যেমন প্রয়োজন অনুযায়ী ফিল্টার ও কিট বিল্ডার (বাজেট দিলে প্রতি শেলফ থেকে একটি পণ্য); ওয়েলনেস কিট — ভেতরে কী আছে ও আসল সাশ্রয় দেখায়; প্রতিটি পণ্যে বেস্ট-বিফোর তারিখ ও সতর্কতা — আপনার সাইটে থাকবে। ডেমোর কাল্পনিক পণ্য ও তথ্যের জায়গায় আপনার লোগো, রং, পণ্য ও যোগাযোগের তথ্য বসবে।', 'package', id, 1 FROM packages WHERE slug = 'prakriti-herbal' AND NOT EXISTS (SELECT 1 FROM faqs f WHERE f.package_id = packages.id AND f.question = 'Prakriti Herbal ডেমোতে যা দেখছি, সবই কি আমার সাইটে থাকবে?');
INSERT INTO faqs (question, answer, scope, package_id, sort_order) SELECT 'অ্যাডমিন প্যানেল থেকে আমি নিজে কী কী করতে পারব?', 'অর্ডার কনফার্ম থেকে ডেলিভারি, ইনভয়েস, পণ্য ও কিট, ব্যাচ ও মেয়াদ, সার্টিফিকেশন, জার্নাল, কুপন, ব্যানার, ডেলিভারি জোন, স্টাফ ও রিপোর্ট — সবই অ্যাডমিন থেকে।', 'package', id, 2 FROM packages WHERE slug = 'prakriti-herbal' AND NOT EXISTS (SELECT 1 FROM faqs f WHERE f.package_id = packages.id AND f.question = 'অ্যাডমিন প্যানেল থেকে আমি নিজে কী কী করতে পারব?');
INSERT INTO faqs (question, answer, scope, package_id, sort_order) SELECT 'দাম কি একবারই? পরে কোনো লুকানো খরচ আছে?', 'সাইট তৈরি ও সেটআপের দাম ৳১২,০০০ — একবারই। ডোমেইন, এসএমএস বা পেমেন্ট গেটওয়ের নিজস্ব চার্জ (যদি নেন) সংশ্লিষ্ট কোম্পানিকে আলাদা দিতে হয় — অর্ডারের আগেই আমরা পরিষ্কার জানিয়ে দেব।', 'package', id, 3 FROM packages WHERE slug = 'prakriti-herbal' AND NOT EXISTS (SELECT 1 FROM faqs f WHERE f.package_id = packages.id AND f.question = 'দাম কি একবারই? পরে কোনো লুকানো খরচ আছে?');
INSERT INTO faqs (question, answer, scope, package_id, sort_order) SELECT 'কত দিনে সাইট পাব?', 'পেমেন্ট নিশ্চিত হওয়ার পর আপনার লোগো, পণ্যের ছবি ও দাম পেলে সাধারণত ৭ কর্মদিবসে। প্রতিটি ধাপের আপডেট আপনার অর্ডার পেজে পাবেন।', 'package', id, 4 FROM packages WHERE slug = 'prakriti-herbal' AND NOT EXISTS (SELECT 1 FROM faqs f WHERE f.package_id = packages.id AND f.question = 'কত দিনে সাইট পাব?');
INSERT INTO faqs (question, answer, scope, package_id, sort_order) SELECT 'মেয়াদ পার হওয়া পণ্য কি বিক্রি হয়ে যেতে পারে?', 'না। ব্যাচ ধরে স্টক রাখা হয় এবং যে ব্যাচের মেয়াদ আগে শেষ সেটিই আগে প্যাক হয় — অ্যাডমিনে মেয়াদের তারিখও দেখা যায়।', 'package', id, 5 FROM packages WHERE slug = 'prakriti-herbal' AND NOT EXISTS (SELECT 1 FROM faqs f WHERE f.package_id = packages.id AND f.question = 'মেয়াদ পার হওয়া পণ্য কি বিক্রি হয়ে যেতে পারে?');
INSERT INTO faqs (question, answer, scope, package_id, sort_order) SELECT 'Sidra Glow Studio ডেমোতে যা দেখছি, সবই কি আমার সাইটে থাকবে?', 'হ্যাঁ। ডেমোর সব ফিচার — যেমন ত্বকের ধরন ও সমস্যা অনুযায়ী ফিল্টার, উপাদান তালিকা ও মেয়াদ; স্কিন কুইজ → বাজেটের মধ্যে স্টকে থাকা পণ্য দিয়ে রুটিন; ফাঁকা সময় দেখে অনলাইনে ফেসিয়াল/ট্রিটমেন্ট বুকিং ও বুকিং নম্বর — আপনার সাইটে থাকবে। ডেমোর কাল্পনিক পণ্য ও তথ্যের জায়গায় আপনার লোগো, রং, পণ্য ও যোগাযোগের তথ্য বসবে।', 'package', id, 1 FROM packages WHERE slug = 'sidra-glow-studio' AND NOT EXISTS (SELECT 1 FROM faqs f WHERE f.package_id = packages.id AND f.question = 'Sidra Glow Studio ডেমোতে যা দেখছি, সবই কি আমার সাইটে থাকবে?');
INSERT INTO faqs (question, answer, scope, package_id, sort_order) SELECT 'অ্যাডমিন প্যানেল থেকে আমি নিজে কী কী করতে পারব?', 'অর্ডার ও ইনভয়েস, স্টুডিওর বুকিং ডায়েরি, ট্রিটমেন্ট, পণ্য ও উপাদান, ব্যাচ ও মেয়াদ, কুপন, ব্যানার, ডেলিভারি জোন, স্টাফ ও রিপোর্ট — সবই অ্যাডমিন থেকে।', 'package', id, 2 FROM packages WHERE slug = 'sidra-glow-studio' AND NOT EXISTS (SELECT 1 FROM faqs f WHERE f.package_id = packages.id AND f.question = 'অ্যাডমিন প্যানেল থেকে আমি নিজে কী কী করতে পারব?');
