INSERT INTO faqs (question, answer, scope, package_id, sort_order) SELECT 'শুধু স্টুডিও বুকিং বা শুধু শপ — একটা নেওয়া যাবে?', 'যাবে। যেটা দরকার নেই সেটা বন্ধ রেখে সাইট সাজিয়ে দেওয়া হবে — দাম একই থাকবে।', 'package', id, 5 FROM packages WHERE slug = 'sidra-glow-studio' AND NOT EXISTS (SELECT 1 FROM faqs f WHERE f.package_id = packages.id AND f.question = 'শুধু স্টুডিও বুকিং বা শুধু শপ — একটা নেওয়া যাবে?');
INSERT INTO faqs (question, answer, scope, package_id, sort_order) SELECT 'Sidra Jewellery & Fashion ডেমোতে যা দেখছি, সবই কি আমার সাইটে থাকবে?', 'হ্যাঁ। ডেমোর সব ফিচার — যেমন অকেশন অনুযায়ী কেনাকাটা: প্রতিদিন, উৎসব ও ব্রাইডাল; কালেকশন ও “কমপ্লিট দ্য লুক” সেট বিক্রি; আংটি ও চুড়ির সাইজ গাইড, প্রতিটি পণ্যে ম্যাটেরিয়াল ও প্লেটিং — আপনার সাইটে থাকবে। ডেমোর কাল্পনিক পণ্য ও তথ্যের জায়গায় আপনার লোগো, রং, পণ্য ও যোগাযোগের তথ্য বসবে।', 'package', id, 1 FROM packages WHERE slug = 'sidra-jewellery' AND NOT EXISTS (SELECT 1 FROM faqs f WHERE f.package_id = packages.id AND f.question = 'Sidra Jewellery & Fashion ডেমোতে যা দেখছি, সবই কি আমার সাইটে থাকবে?');
