INSERT INTO faqs (question, answer, scope, package_id, sort_order) SELECT 'সাইজ গাইড কি আমার মাপ অনুযায়ী বদলানো যাবে?', 'হ্যাঁ। আংটি ও চুড়ির সাইজ গাইড আপনার দোকানের মাপ অনুযায়ী সাজিয়ে দেওয়া হবে।', 'package', id, 5 FROM packages WHERE slug = 'sidra-jewellery' AND NOT EXISTS (SELECT 1 FROM faqs f WHERE f.package_id = packages.id AND f.question = 'সাইজ গাইড কি আমার মাপ অনুযায়ী বদলানো যাবে?');
INSERT INTO faqs (question, answer, scope, package_id, sort_order) SELECT 'Zamil Shop BD ডেমোতে যা দেখছি, সবই কি আমার সাইটে থাকবে?', 'হ্যাঁ। ডেমোর সব ফিচার — যেমন বয়স অনুযায়ী কেনাকাটা (০–৬ মাস থেকে ৫ বছর); গিফট ফাইন্ডার ও শেয়ারযোগ্য গিফট রেজিস্ট্রি; সার্টিফিকেট সংযুক্ত থাকলেই কেবল সেফটি ব্যাজ — আপনার সাইটে থাকবে। ডেমোর কাল্পনিক পণ্য ও তথ্যের জায়গায় আপনার লোগো, রং, পণ্য ও যোগাযোগের তথ্য বসবে।', 'package', id, 1 FROM packages WHERE slug = 'zamil-shop-bd' AND NOT EXISTS (SELECT 1 FROM faqs f WHERE f.package_id = packages.id AND f.question = 'Zamil Shop BD ডেমোতে যা দেখছি, সবই কি আমার সাইটে থাকবে?');
