INSERT INTO faqs (question, answer, scope, package_id, sort_order) SELECT 'গিফট রেজিস্ট্রি কীভাবে কাজ করে?', 'নতুন বাবা-মা পছন্দের পণ্যের তালিকা বানিয়ে লিংক শেয়ার করেন; আত্মীয়-বন্ধুরা সেই তালিকা থেকে কিনে উপহার পাঠান।', 'package', id, 5 FROM packages WHERE slug = 'zamil-shop-bd' AND NOT EXISTS (SELECT 1 FROM faqs f WHERE f.package_id = packages.id AND f.question = 'গিফট রেজিস্ট্রি কীভাবে কাজ করে?');
INSERT INTO faqs (question, answer, scope, package_id, sort_order) SELECT 'Veloura Atelier ডেমোতে যা দেখছি, সবই কি আমার সাইটে থাকবে?', 'হ্যাঁ। ডেমোর সব ফিচার — যেমন ১০টি ক্রেতা-মুখী স্ক্রিন: ক্যাটালগ থেকে অর্ডার ট্র্যাকিং; কাস্টমার অ্যাকাউন্ট ও প্রিন্টযোগ্য ইনভয়েস; ব্লগ/জার্নাল সেকশন — আপনার সাইটে থাকবে। ডেমোর কাল্পনিক পণ্য ও তথ্যের জায়গায় আপনার লোগো, রং, পণ্য ও যোগাযোগের তথ্য বসবে।', 'package', id, 1 FROM packages WHERE slug = 'veloura-atelier' AND NOT EXISTS (SELECT 1 FROM faqs f WHERE f.package_id = packages.id AND f.question = 'Veloura Atelier ডেমোতে যা দেখছি, সবই কি আমার সাইটে থাকবে?');
INSERT INTO faqs (question, answer, scope, package_id, sort_order) SELECT 'অ্যাডমিন প্যানেল থেকে আমি নিজে কী কী করতে পারব?', 'অর্ডার, ক্যাটালগ, স্টক, কুরিয়ার বুকিং, পিওএস ও বারকোড, রিটার্ন, রিভিউ ও কনটেন্ট — সবই অ্যাডমিন থেকে।', 'package', id, 2 FROM packages WHERE slug = 'veloura-atelier' AND NOT EXISTS (SELECT 1 FROM faqs f WHERE f.package_id = packages.id AND f.question = 'অ্যাডমিন প্যানেল থেকে আমি নিজে কী কী করতে পারব?');
INSERT INTO faqs (question, answer, scope, package_id, sort_order) SELECT 'দাম কি একবারই? পরে কোনো লুকানো খরচ আছে?', 'সাইট তৈরি ও সেটআপের দাম ৳১২,০০০ — একবারই। ডোমেইন, এসএমএস বা পেমেন্ট গেটওয়ের নিজস্ব চার্জ (যদি নেন) সংশ্লিষ্ট কোম্পানিকে আলাদা দিতে হয় — অর্ডারের আগেই আমরা পরিষ্কার জানিয়ে দেব।', 'package', id, 3 FROM packages WHERE slug = 'veloura-atelier' AND NOT EXISTS (SELECT 1 FROM faqs f WHERE f.package_id = packages.id AND f.question = 'দাম কি একবারই? পরে কোনো লুকানো খরচ আছে?');
INSERT INTO faqs (question, answer, scope, package_id, sort_order) SELECT 'কত দিনে সাইট পাব?', 'পেমেন্ট নিশ্চিত হওয়ার পর আপনার লোগো, পণ্যের ছবি ও দাম পেলে সাধারণত ৭ কর্মদিবসে। প্রতিটি ধাপের আপডেট আপনার অর্ডার পেজে পাবেন।', 'package', id, 4 FROM packages WHERE slug = 'veloura-atelier' AND NOT EXISTS (SELECT 1 FROM faqs f WHERE f.package_id = packages.id AND f.question = 'কত দিনে সাইট পাব?');
INSERT INTO faqs (question, answer, scope, package_id, sort_order) SELECT 'SmartGadget ডেমোতে যা দেখছি, সবই কি আমার সাইটে থাকবে?', 'হ্যাঁ। ডেমোর সব ফিচার — যেমন পরিমাণ বাড়লে ধাপে ধাপে কমে যাওয়া পাইকারি দাম, প্রতিটি পণ্যে দেখানো; ক্যাটালগ, পণ্যের পেজ, কার্ট, চেকআউট ও অর্ডার ট্র্যাকিং; অ্যাডমিন: পণ্য, স্টক, অর্ডার, কাস্টমার, রিভিউ, কনটেন্ট ও অ্যানালিটিক্স — আপনার সাইটে থাকবে। ডেমোর কাল্পনিক পণ্য ও তথ্যের জায়গায় আপনার লোগো, রং, পণ্য ও যোগাযোগের তথ্য বসবে।', 'package', id, 1 FROM packages WHERE slug = 'smartgadget-wholesale' AND NOT EXISTS (SELECT 1 FROM faqs f WHERE f.package_id = packages.id AND f.question = 'SmartGadget ডেমোতে যা দেখছি, সবই কি আমার সাইটে থাকবে?');
INSERT INTO faqs (question, answer, scope, package_id, sort_order) SELECT 'অ্যাডমিন প্যানেল থেকে আমি নিজে কী কী করতে পারব?', 'পণ্য ও পাইকারি দাম, স্টক, অর্ডার, কাস্টমার, রিভিউ, কনটেন্ট ও অ্যানালিটিক্স — ১৪টি স্ক্রিনের অ্যাডমিন থেকে।', 'package', id, 2 FROM packages WHERE slug = 'smartgadget-wholesale' AND NOT EXISTS (SELECT 1 FROM faqs f WHERE f.package_id = packages.id AND f.question = 'অ্যাডমিন প্যানেল থেকে আমি নিজে কী কী করতে পারব?');
