INSERT INTO faqs (question, answer, scope, package_id, sort_order) SELECT 'কত দিনে সাইট পাব?', 'পেমেন্ট নিশ্চিত হওয়ার পর আপনার লোগো, পণ্যের ছবি ও দাম পেলে সাধারণত ১০ কর্মদিবসে। প্রতিটি ধাপের আপডেট আপনার অর্ডার পেজে পাবেন।', 'package', id, 4 FROM packages WHERE slug = 'smartgadget-wholesale' AND NOT EXISTS (SELECT 1 FROM faqs f WHERE f.package_id = packages.id AND f.question = 'কত দিনে সাইট পাব?');
INSERT INTO faqs (question, answer, scope, package_id, sort_order) SELECT 'খুচরা ও পাইকারি দুই দামই রাখা যাবে?', 'যাবে। প্রতিটি পণ্যে পরিমাণভিত্তিক দামের ধাপ থাকে — ১ পিসের দাম খুচরা, বেশি পিসে পাইকারি।', 'package', id, 5 FROM packages WHERE slug = 'smartgadget-wholesale' AND NOT EXISTS (SELECT 1 FROM faqs f WHERE f.package_id = packages.id AND f.question = 'খুচরা ও পাইকারি দুই দামই রাখা যাবে?');
INSERT INTO faqs (question, answer, scope, package_id, sort_order) SELECT 'Sidra Noor Fashion ডেমোতে যা দেখছি, সবই কি আমার সাইটে থাকবে?', 'হ্যাঁ। ডেমোর সব ফিচার — যেমন ক্যাটাগরি পেজ, পণ্যের পেজ, কার্ট ও চেকআউট; অ্যাডমিনের ৮টি স্ক্রিন: ড্যাশবোর্ড, পণ্য, অর্ডার, কাস্টমার, মেসেজ, স্টাফ, প্রোফাইল, পণ্য এডিটর; স্টোর ও অ্যাডমিন একই ক্যাটালগে — কোনো গরমিল নেই — আপনার সাইটে থাকবে। ডেমোর কাল্পনিক পণ্য ও তথ্যের জায়গায় আপনার লোগো, রং, পণ্য ও যোগাযোগের তথ্য বসবে।', 'package', id, 1 FROM packages WHERE slug = 'sidra-noor-fashion' AND NOT EXISTS (SELECT 1 FROM faqs f WHERE f.package_id = packages.id AND f.question = 'Sidra Noor Fashion ডেমোতে যা দেখছি, সবই কি আমার সাইটে থাকবে?');
