INSERT INTO faqs (question, answer, scope, package_id, sort_order) SELECT 'Bootstrap Fashion ডেমোতে যা দেখছি, সবই কি আমার সাইটে থাকবে?', 'হ্যাঁ। ডেমোর সব ফিচার — যেমন হোমপেজ, লাইভ ফিল্টার ও প্রাইস স্লাইডারসহ ক্যাটাগরি তালিকা; গ্যালারি ও রিভিউসহ পণ্যের পেজ, কার্ট; শিপিং ও পেমেন্টসহ তিন ধাপের চেকআউট, প্রতিটি আবশ্যক ঘর চিহ্নিত — আপনার সাইটে থাকবে। ডেমোর কাল্পনিক পণ্য ও তথ্যের জায়গায় আপনার লোগো, রং, পণ্য ও যোগাযোগের তথ্য বসবে।', 'package', id, 1 FROM packages WHERE slug = 'bootstrap-fashion' AND NOT EXISTS (SELECT 1 FROM faqs f WHERE f.package_id = packages.id AND f.question = 'Bootstrap Fashion ডেমোতে যা দেখছি, সবই কি আমার সাইটে থাকবে?');
INSERT INTO faqs (question, answer, scope, package_id, sort_order) SELECT 'অ্যাডমিন প্যানেল থেকে আমি নিজে কী কী করতে পারব?', 'ড্যাশবোর্ড, পণ্য, অর্ডার ও কাস্টমার দেখার অ্যাডমিন। পূর্ণ ব্যাকএন্ড লাগলে আলাদা কোটেশনে যুক্ত করে দেওয়া হয়।', 'package', id, 2 FROM packages WHERE slug = 'bootstrap-fashion' AND NOT EXISTS (SELECT 1 FROM faqs f WHERE f.package_id = packages.id AND f.question = 'অ্যাডমিন প্যানেল থেকে আমি নিজে কী কী করতে পারব?');
INSERT INTO faqs (question, answer, scope, package_id, sort_order) SELECT 'দাম কি একবারই? পরে কোনো লুকানো খরচ আছে?', 'সাইট তৈরি ও সেটআপের দাম ৳১২,০০০ — একবারই। ডোমেইন, এসএমএস বা পেমেন্ট গেটওয়ের নিজস্ব চার্জ (যদি নেন) সংশ্লিষ্ট কোম্পানিকে আলাদা দিতে হয় — অর্ডারের আগেই আমরা পরিষ্কার জানিয়ে দেব।', 'package', id, 3 FROM packages WHERE slug = 'bootstrap-fashion' AND NOT EXISTS (SELECT 1 FROM faqs f WHERE f.package_id = packages.id AND f.question = 'দাম কি একবারই? পরে কোনো লুকানো খরচ আছে?');
INSERT INTO faqs (question, answer, scope, package_id, sort_order) SELECT 'কত দিনে সাইট পাব?', 'পেমেন্ট নিশ্চিত হওয়ার পর আপনার লোগো, পণ্যের ছবি ও দাম পেলে সাধারণত ৭ কর্মদিবসে। প্রতিটি ধাপের আপডেট আপনার অর্ডার পেজে পাবেন।', 'package', id, 4 FROM packages WHERE slug = 'bootstrap-fashion' AND NOT EXISTS (SELECT 1 FROM faqs f WHERE f.package_id = packages.id AND f.question = 'কত দিনে সাইট পাব?');
INSERT INTO faqs (question, answer, scope, package_id, sort_order) SELECT 'এই টেমপ্লেটে কি অর্ডার সত্যিই জমা হয়?', 'ডেমোটি শুধু ফ্রন্ট-এন্ড। আপনার বর্তমান সিস্টেমের সাথে যুক্ত করা যায়, অথবা পূর্ণ ব্যাকএন্ড চাইলে কোটেশন নিন — আমাদের অন্য রেডি শপগুলোতে পূর্ণ ব্যাকএন্ড আগে থেকেই আছে।', 'package', id, 5 FROM packages WHERE slug = 'bootstrap-fashion' AND NOT EXISTS (SELECT 1 FROM faqs f WHERE f.package_id = packages.id AND f.question = 'এই টেমপ্লেটে কি অর্ডার সত্যিই জমা হয়?');
INSERT INTO faqs (question, answer, scope, package_id, sort_order) SELECT 'SmartGen Commerce OS ডেমোতে যা দেখছি, সবই কি আমার সাইটে থাকবে?', 'হ্যাঁ। ডেমোর সব ফিচার — যেমন ক্যাটালগ ও কাস্টমার ম্যানেজমেন্ট; পারফরম্যান্স অ্যানালিটিক্সসহ ক্যাম্পেইন বিল্ডার; প্রো-টিয়ার ফিচার গেটিং ইউআই-তেই তৈরি — আপনার সাইটে থাকবে। ডেমোর কাল্পনিক পণ্য ও তথ্যের জায়গায় আপনার লোগো, রং, পণ্য ও যোগাযোগের তথ্য বসবে।', 'package', id, 1 FROM packages WHERE slug = 'smartgen-commerce-os' AND NOT EXISTS (SELECT 1 FROM faqs f WHERE f.package_id = packages.id AND f.question = 'SmartGen Commerce OS ডেমোতে যা দেখছি, সবই কি আমার সাইটে থাকবে?');
INSERT INTO faqs (question, answer, scope, package_id, sort_order) SELECT 'অ্যাডমিন প্যানেল থেকে আমি নিজে কী কী করতে পারব?', 'ক্যাটালগ, কাস্টমার, ক্যাম্পেইন ও অ্যানালিটিক্স — সব এক সফটওয়্যারে।', 'package', id, 2 FROM packages WHERE slug = 'smartgen-commerce-os' AND NOT EXISTS (SELECT 1 FROM faqs f WHERE f.package_id = packages.id AND f.question = 'অ্যাডমিন প্যানেল থেকে আমি নিজে কী কী করতে পারব?');
