INSERT INTO faqs (question, answer, scope, package_id, sort_order) SELECT 'কত দিনে সাইট পাব?', 'পেমেন্ট নিশ্চিত হওয়ার পর আপনার লোগো, পণ্যের ছবি ও দাম পেলে সাধারণত ১০ কর্মদিবসে। প্রতিটি ধাপের আপডেট আপনার অর্ডার পেজে পাবেন।', 'package', id, 4 FROM packages WHERE slug = 'smartgen-commerce-os' AND NOT EXISTS (SELECT 1 FROM faqs f WHERE f.package_id = packages.id AND f.question = 'কত দিনে সাইট পাব?');
INSERT INTO faqs (question, answer, scope, package_id, sort_order) SELECT 'Northstar Admin ডেমোতে যা দেখছি, সবই কি আমার সাইটে থাকবে?', 'হ্যাঁ। ডেমোর সব ফিচার — যেমন ফিল্টার ও বাল্ক অ্যাকশনসহ অর্ডার কিউ; ইউজার ম্যানেজমেন্ট ও রোল সেটিংস; প্রোডাক্টের ভেতরেই হেল্প ও ডকুমেন্টেশন — আপনার সাইটে থাকবে। ডেমোর কাল্পনিক পণ্য ও তথ্যের জায়গায় আপনার লোগো, রং, পণ্য ও যোগাযোগের তথ্য বসবে।', 'package', id, 1 FROM packages WHERE slug = 'northstar-admin' AND NOT EXISTS (SELECT 1 FROM faqs f WHERE f.package_id = packages.id AND f.question = 'Northstar Admin ডেমোতে যা দেখছি, সবই কি আমার সাইটে থাকবে?');
INSERT INTO faqs (question, answer, scope, package_id, sort_order) SELECT 'অ্যাডমিন প্যানেল থেকে আমি নিজে কী কী করতে পারব?', 'অর্ডার, ইউজার ও রোল, সেটিংস ও হেল্প — সবই এই কনসোল থেকে।', 'package', id, 2 FROM packages WHERE slug = 'northstar-admin' AND NOT EXISTS (SELECT 1 FROM faqs f WHERE f.package_id = packages.id AND f.question = 'অ্যাডমিন প্যানেল থেকে আমি নিজে কী কী করতে পারব?');
