INSERT INTO faqs (question, answer, scope, package_id, sort_order) SELECT 'Rinova BD ডেমোতে যা দেখছি, সবই কি আমার সাইটে থাকবে?', 'হ্যাঁ। ডেমোর সব ফিচার — যেমন প্রতিটি অবস্থার অর্ডার পাইপলাইন ও কুরিয়ারের অবস্থা; খরচ, মার্জিন ও রিস্টক সীমাসহ ক্যাটালগ; পিওএস, বারকোড লেবেল, অফার, স্টাফ রোল ও রিটার্ন — আপনার সাইটে থাকবে। ডেমোর কাল্পনিক পণ্য ও তথ্যের জায়গায় আপনার লোগো, রং, পণ্য ও যোগাযোগের তথ্য বসবে।', 'package', id, 1 FROM packages WHERE slug = 'rinova-admin' AND NOT EXISTS (SELECT 1 FROM faqs f WHERE f.package_id = packages.id AND f.question = 'Rinova BD ডেমোতে যা দেখছি, সবই কি আমার সাইটে থাকবে?');
INSERT INTO faqs (question, answer, scope, package_id, sort_order) SELECT 'অ্যাডমিন প্যানেল থেকে আমি নিজে কী কী করতে পারব?', 'অর্ডার ও কুরিয়ার, ক্যাটালগ, স্টক, পিওএস ও বারকোড, অফার, স্টাফ রোল, রিটার্ন ও অ্যানালিটিক্স — সব এক অ্যাডমিন থেকে।', 'package', id, 2 FROM packages WHERE slug = 'rinova-admin' AND NOT EXISTS (SELECT 1 FROM faqs f WHERE f.package_id = packages.id AND f.question = 'অ্যাডমিন প্যানেল থেকে আমি নিজে কী কী করতে পারব?');
