INSERT INTO faqs (question, answer, scope, package_id, sort_order) SELECT 'এটি কি আসল চালু সাইট?', 'হ্যাঁ। vandarmart.com আমরা ABS VAI LTD-এর জন্য তৈরি করে ডেলিভারি দিয়েছি এবং এটি এখন চালু আছে। একই সিস্টেম আপনার ব্র্যান্ড ও পণ্য দিয়ে বানিয়ে দেওয়া হবে।', 'package', id, 1 FROM packages WHERE slug = 'vandarmart' AND NOT EXISTS (SELECT 1 FROM faqs f WHERE f.package_id = packages.id AND f.question = 'এটি কি আসল চালু সাইট?');
INSERT INTO faqs (question, answer, scope, package_id, sort_order) SELECT 'আমার পণ্য খাবার না হলেও কি চলবে?', 'চলবে। প্রতিটি ক্যাটাগরির জন্য আলাদা টেমপ্লেট থাকে — ওজন, ভলিউম, মিটার, সাইজ, রং বা মডেল — তাই পোশাক, গ্যাজেট, মেশিন বা খাবার সব একসাথে বিক্রি করা যায়।', 'package', id, 2 FROM packages WHERE slug = 'vandarmart' AND NOT EXISTS (SELECT 1 FROM faqs f WHERE f.package_id = packages.id AND f.question = 'আমার পণ্য খাবার না হলেও কি চলবে?');
INSERT INTO faqs (question, answer, scope, package_id, sort_order) SELECT 'অ্যাডমিন প্যানেল থেকে আমি নিজে কী কী করতে পারব?', 'পণ্য আপলোড ও স্টক, অর্ডারের ৮টি ধাপ, ইনভয়েস ও বারকোড প্রিন্ট, কুরিয়ার, অসম্পূর্ণ অর্ডার, ম্যানুয়াল অর্ডার, সিজন, ব্যানার, স্টাফ রোল, ব্লক লিস্ট আর সব সেটিংস — কোড ছাড়াই।', 'package', id, 3 FROM packages WHERE slug = 'vandarmart' AND NOT EXISTS (SELECT 1 FROM faqs f WHERE f.package_id = packages.id AND f.question = 'অ্যাডমিন প্যানেল থেকে আমি নিজে কী কী করতে পারব?');
INSERT INTO faqs (question, answer, scope, package_id, sort_order) SELECT 'কুরিয়ার কি সরাসরি বুক হয়?', 'Steadfast ও Pathao-র অ্যাকাউন্ট থাকলে অ্যাডমিন থেকেই পার্সেল বুক হয়। RedX বা Carrybee-তে ট্র্যাকিং আইডি লিখে দিলেই চলে।', 'package', id, 4 FROM packages WHERE slug = 'vandarmart' AND NOT EXISTS (SELECT 1 FROM faqs f WHERE f.package_id = packages.id AND f.question = 'কুরিয়ার কি সরাসরি বুক হয়?');
INSERT INTO faqs (question, answer, scope, package_id, sort_order) SELECT 'দাম কি একবারই? পরে কোনো লুকানো খরচ আছে?', 'সাইট তৈরি ও সেটআপের দাম ৳১২,০০০ — একবারই। ডোমেইন, এসএমএস বা কুরিয়ার/পেমেন্ট গেটওয়ের নিজস্ব চার্জ (যদি নেন) সংশ্লিষ্ট কোম্পানিকে আলাদা দিতে হয় — অর্ডারের আগেই পরিষ্কার জানিয়ে দেব।', 'package', id, 5 FROM packages WHERE slug = 'vandarmart' AND NOT EXISTS (SELECT 1 FROM faqs f WHERE f.package_id = packages.id AND f.question = 'দাম কি একবারই? পরে কোনো লুকানো খরচ আছে?');
INSERT INTO faqs (question, answer, scope, package_id, sort_order) SELECT 'কত দিনে সাইট পাব?', 'পেমেন্ট নিশ্চিত হওয়ার পর আপনার লোগো, পণ্যের ছবি ও দাম পেলে সাধারণত ১৪ কর্মদিবসে। প্রতিটি ধাপের আপডেট আপনার অর্ডার পেজে পাবেন।', 'package', id, 6 FROM packages WHERE slug = 'vandarmart' AND NOT EXISTS (SELECT 1 FROM faqs f WHERE f.package_id = packages.id AND f.question = 'কত দিনে সাইট পাব?');
